      "var": "gel nail paint units",
      "coef": 3.0
     },
     {
      "var": "acrylic nail paint units",
      "coef": 5.0
     }
    ],
    "sense": "<=",
    "rhs": 480.0
   },
   {
    "name": "packing hours",
    "terms": [
