      "var": "gel nail paint units",
      "coef": 6.0
     },
     {
      "var": "acrylic nail paint units",
      "coef": 2.3
     }
    ],
    "sense": "<=",
    "rhs": 510.0
   }
  ]
 },
 "facts": {
